mapper.select:
select v.* from ( select cc.contract_id, cc.contract_number, cc.legal_contracT_number, cc.contract_name, ccb.bank_account_id, cc.project_id, CASE WHEN cc.BUSINESS_TYPE in ('T+N_LEASE_FACTORING', 'T+0_LEASE_FACTORING') THEN (SELECT dbms_lob.substr(wm_concat(b.bp_name)) FROM hls_bp_master b, prj_project_bp hclcb WHERE cc.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'ACCOUNTS_RECEIVABLE') WHEN cc.BUSINESS_TYPE in ('LEASE_WITHOUT_RECOURSE_IN', 'OPERATING_LEASE_WITHOUT_RECOURSE_IN') THEN (SELECT dbms_lob.substr(wm_concat(b.bp_name)) FROM hls_bp_master b, prj_project_bp hclcb WHERE cc.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'ASSET_TRANSFEROR') ELSE (SELECT dbms_lob.substr(wm_concat(b.bp_name)) FROM hls_bp_master b, prj_project_bp hclcb WHERE cc.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'TENANT') END AS tenant_id_n,
cc.contract_amount, (SELECT a.description FROM sys_user a WHERE a.user_id = cc.host_project_manager) host_project_manager_n, ccb.invoice_kind, (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb where scb.code = 'VAT.INVOICE_KIND' and scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scvb.value in ('0', '2') and scvb.value = ccb.invoice_kind) invoice_kind_n, nvl(ccb.billing_way,1) billing_way, (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb where scb.code = 'VAT.BILLING_WAY' and scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scvb.value = nvl(ccb.billing_way,1)) billing_way_n, ccb.product_name, ccb.bp_id, (select sbm.bp_name from hls_bp_master sbm where sbm.bp_id = ccb.bp_id) as bp_id_n, ccb.bp_tax_registry_num, ccb.bp_address_phone_num, ccb.bp_bank_account, ccb.tax_type_rate, (select scvb.meaning from sys_code_value_b scvb, sys_code_b scb where scb.code = 'ABS.ADD_TAX_RATE' and scb.code_id = scvb.code_id and scvb.enabled_flag = 'Y' and scvb.value in('0.06','0.13') and scvb.value = ccb.tax_type_rate) tax_type_rate_n
from con_contract cc left join con_contract_bank_account ccb on cc.contract_id = ccb.contract_id ) v
and v.contract_number = #{contractNumber}
and v.legal_contract_number LIKE concat('%',concat(#{legalContractNumber},'%') )
and v.contract_name = #{contractName}
and v.tenant_id_n = #{bpName}
and v.host_project_manager_n = #{employeeIdN}
